import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('getisord_no2_Q4_2023.csv')
adjacency = pd.read_csv('borough_adjacency.csv')

# Handle missing values in the avg_no2_value column by replacing them with the citywide average
citywide_avg = data['avg_no2_value'].mean()
data['avg_no2_value'] = data['avg_no2_value'].fillna(citywide_avg)

# Create a list of neighboring boroughs for each borough
adjacency_list = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in adjacency_list:
        adjacency_list[row['borough']] = []
    adjacency_list[row['borough']].append(row['neighbor'])

# Compute the Gi* statistic for each local area
gi_values = {}
for borough, neighbors in adjacency_list.items():
    local_area = data[data['borough'] == borough]
    if local_area['avg_no2_value'].isnull().any():
        continue
    local_area = local_area.append(data[~data['borough'].isin(neighbors)])
    gi_value = (local_area['avg_no2_value'] - citywide_avg) / np.std(local_area['avg_no2_value'])
    gi_values[borough] = gi_value

# Identify hot and cold spots
hot_cold_spots = {}
for borough, gi_value in gi_values.items():
    if np.abs(gi_value) > 1.96:
        hot_cold_spots[borough] = gi_value

# Report results
data_points_used = len(data) - data['avg_no2_value'].isnull().sum()
print(f"data_points_used = {data_points_used}")
if hot_cold_spots:
    print(f"FINAL ANSWER: {', '.join(f'{borough} (HOT, Gi*={gi_value:.4f})' if gi_value > 0 else f'{borough} (COLD, Gi*={gi_value:.4f})' for borough, gi_value in hot_cold_spots.items())}")
else:
    print("FINAL ANSWER: none")
